		Run: jobs.NewRun(jobs.KindScan, command.ViewWorkspaces, "", "~/work", "/repos/a", "/repos/b"),
		Work: func(contextName string) tea.Cmd {
			return func() tea.Msg { worked = contextName; return nil }
		},
	})

