	if len(snapshot) != 1 {
		t.Fatalf("the registry holds %d runs, want 1", len(snapshot))
	}
	if got, want := snapshot[0].Context, "prod"; got != want {
		t.Errorf("Context = %q, want %q — the router stamps it, not the view", got, want)
	}
